CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS TRIGGER AS $ 
BEGIN 
    IF NEW.resstat = 'Resolved' THEN 
        -- Assuming 'invdetref' links to a table with 'iii' column
        IF EXISTS (
            SELECT 1 
            FROM investigationdetails 
            WHERE invdetreg = NEW.invdetref 
            AND mktabprob > 75.0 
        ) THEN 
            RAISE EXCEPTION 'Premature resolution blocked: III exceeds threshold'; 
        END IF; 
    END IF; 
    RETURN NEW; 
END; 
$ LANGUAGE plpgsql;

CREATE TRIGGER prevent_premature_resolution
BEFORE UPDATE ON enforcementactions
FOR EACH ROW EXECUTE FUNCTION check_premature_resolution();

